-- gsk hosted d1_export — schema + data
CREATE TABLE admin_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, token TEXT UNIQUE NOT NULL, role TEXT NOT NULL DEFAULT 'admin', label TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT (DATETIME('now')), expires_at TEXT NOT NULL);
CREATE TABLE admin_users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL, role TEXT NOT NULL DEFAULT 'staff', label TEXT DEFAULT '', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (DATETIME('now')));
CREATE TABLE app_contents (id INTEGER PRIMARY KEY AUTOINCREMENT, section TEXT NOT NULL CHECK (section IN ('shopping', 'news')), title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', address TEXT, sort_order INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN', 'HIDDEN')), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE attendance_records (id INTEGER PRIMARY KEY AUTOINCREMENT, roadshow_code TEXT NOT NULL, cw_no TEXT NOT NULL, clock_in_at TEXT, clock_in_lat REAL, clock_in_lng REAL, clock_in_dist INTEGER, clock_in_selfie TEXT, clock_out_at TEXT, clock_out_lat REAL, clock_out_lng REAL, clock_out_dist INTEGER, clock_out_selfie TEXT, worked_minutes INTEGER NOT NULL DEFAULT 0, is_manual INTEGER NOT NULL DEFAULT 0, manual_by TEXT, manual_reason TEXT, flag TEXT, created_at TEXT NOT NULL DEFAULT (DATETIME('now')), updated_at TEXT NOT NULL DEFAULT (DATETIME('now')), UNIQUE (roadshow_code, cw_no));
CREATE TABLE authorization_cards (id INTEGER PRIMARY KEY AUTOINCREMENT, token TEXT NOT NULL UNIQUE /* 隨機碼，非順序 */, holder_no TEXT NOT NULL REFERENCES role_holders (holder_no) ON DELETE CASCADE, card_type TEXT NOT NULL CHECK (card_type IN ('NEGOTIATION', 'PROJECT')), project_id INTEGER DEFAULT NULL REFERENCES projects (id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'VALID' CHECK (status IN ('VALID', 'EXPIRED', 'REVOKED')), issued_at TEXT NOT NULL DEFAULT (DATETIME('now')), expires_at TEXT DEFAULT NULL /* 洽商卡 = issued_at + 90 天 */, created_at TEXT NOT NULL DEFAULT (DATETIME('now')));
CREATE TABLE bundle_addons (id INTEGER PRIMARY KEY AUTOINCREMENT, bundle_id INTEGER NOT NULL, product_id INTEGER, name_zh TEXT NOT NULL /* 加購品中文名（例：多一包紙巾） */, name_en TEXT /* 加購品英文名 */, quantity INTEGER DEFAULT 1, addon_price REAL DEFAULT 0 /* 加購價（例：$1、$5） */, normal_value REAL DEFAULT 0 /* 正常市值（顯示慳幾多） */, description TEXT, photo_url TEXT, sort_order INTEGER DEFAULT 0, FOREIGN KEY (bundle_id) REFERENCES bundles (id));
CREATE TABLE bundle_gifts (id INTEGER PRIMARY KEY AUTOINCREMENT, bundle_id INTEGER NOT NULL, product_id INTEGER, name_zh TEXT NOT NULL /* 贈品中文名 */, name_en TEXT /* 贈品英文名 */, quantity INTEGER DEFAULT 1, unit_value REAL DEFAULT 0 /* 該贈品市值（用來加總「送價值 $X」） */, description TEXT, photo_url TEXT, sort_order INTEGER DEFAULT 0, FOREIGN KEY (bundle_id) REFERENCES bundles (id));
CREATE TABLE bundle_items (id INTEGER PRIMARY KEY AUTOINCREMENT, bundle_id INTEGER NOT NULL, product_id INTEGER /* 連到 products（可為 NULL 表示自由輸入） */, name_zh TEXT NOT NULL /* 冗餘存中文名（套裝快照，即使產品改名不變） */, name_en TEXT /* 冗餘存英文名 */, quantity INTEGER DEFAULT 1 /* 數量 */, unit_price REAL DEFAULT 0 /* 該產品單價（此套裝內） */, description TEXT /* 該產品描述 */, photo_url TEXT /* 該產品相片 */, sort_order INTEGER DEFAULT 0, FOREIGN KEY (bundle_id) REFERENCES bundles (id));
CREATE TABLE bundles (id INTEGER PRIMARY KEY AUTOINCREMENT, name_zh TEXT NOT NULL /* 套裝中文名（例：長者健康入門套裝） */, name_en TEXT /* 套裝英文名 */, description TEXT /* 套裝描述 */, bundle_price REAL DEFAULT 0 /* 套裝售價（客人付這個價） */, photo_url TEXT /* 套裝主相片（選填） */, status TEXT DEFAULT 'ACTIVE' /* ACTIVE / ARCHIVED */, created_at TEXT NOT NULL DEFAULT (DATETIME('now')));
CREATE TABLE co_partner_counter (id INTEGER PRIMARY KEY DEFAULT 1, next_val INTEGER NOT NULL DEFAULT 0);
CREATE TABLE co_partners (id INTEGER PRIMARY KEY AUTOINCREMENT, partner_no TEXT NOT NULL UNIQUE /* CP000001 */, name TEXT NOT NULL, partner_type TEXT NOT NULL CHECK (partner_type IN ('SUPPLIER', 'BRAND', 'RETAIL')), contact TEXT DEFAULT '', terms_notes TEXT DEFAULT '' /* 合作條款（如寄賣比例） */, disclosure_level TEXT NOT NULL DEFAULT 'GENERIC' CHECK (disclosure_level IN ('PUBLIC', 'GENERIC', 'ANONYMOUS')), created_at TEXT NOT NULL DEFAULT (DATETIME('now')));
CREATE TABLE co_workery (id INTEGER PRIMARY KEY AUTOINCREMENT, cw_no TEXT NOT NULL UNIQUE, member_no TEXT NOT NULL, name_zh TEXT NOT NULL, name_en TEXT, phone TEXT NOT NULL, gender TEXT, birth_year INTEGER, address TEXT, district TEXT, hkid_prefix TEXT, id_front_key TEXT, bank_name TEXT, bank_account_name TEXT, bank_account_no TEXT, default_hourly_rate INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'PENDING', reject_reason TEXT, approved_by TEXT, approved_at TEXT, created_at TEXT NOT NULL DEFAULT (DATETIME('now')), updated_at TEXT NOT NULL DEFAULT (DATETIME('now')), bank_account TEXT DEFAULT NULL);
CREATE TABLE counter (
  id INTEGER PRIMARY KEY CHECK (id = 1),  
  next_val INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE coworkery_counter (id INTEGER PRIMARY KEY CHECK (id = 1), next_val INTEGER NOT NULL DEFAULT 0);
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE feedback_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, thread_id INTEGER NOT NULL, sender TEXT NOT NULL CHECK (sender IN ('member', 'admin')), content TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE feedback_threads (id INTEGER PRIMARY KEY AUTOINCREMENT, member_no TEXT NOT NULL, member_name TEXT NOT NULL DEFAULT '', subject TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'replied', 'closed')), has_unread_for_member INTEGER NOT NULL DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE hash_chain (id INTEGER PRIMARY KEY AUTOINCREMENT, record_type TEXT NOT NULL /* 'SETTLEMENT' / 'WALLET_POSTED' / 'WALLET_PAYOUT' / 'WALLET_PAID' / 'CARD_ISSUED' / 'CARD_REVOKED' */, record_id INTEGER NOT NULL /* 對應表的 id */, sha256 TEXT NOT NULL, prev_hash TEXT NOT NULL DEFAULT '' /* 首筆為空字串 */, created_at TEXT NOT NULL DEFAULT (DATETIME('now')));
CREATE TABLE jhc_stores (id INTEGER PRIMARY KEY AUTOINCREMENT, store_code TEXT UNIQUE NOT NULL /* e.g. "APM", "MK" */, name_zh TEXT NOT NULL /* Chinese name */, name_en TEXT /* English name */, district TEXT /* District / region */, address TEXT /* Full address */, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (DATETIME('now')));
CREATE TABLE job_applications (id INTEGER PRIMARY KEY AUTOINCREMENT, job_id INTEGER NOT NULL, member_no TEXT NOT NULL, applied_at TEXT DEFAULT (DATETIME('now')), handle_status TEXT DEFAULT 'new', UNIQUE (job_id, member_no));
CREATE TABLE jobs (id INTEGER PRIMARY KEY AUTOINCREMENT, image_url TEXT, title TEXT NOT NULL, location TEXT, job_type TEXT, company TEXT, description TEXT, requirement TEXT, salary TEXT, status TEXT DEFAULT 'open', sort_order INTEGER DEFAULT 0, created_at TEXT DEFAULT (DATETIME('now')));
CREATE TABLE medical_card_applications (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  member_no TEXT NOT NULL,              
  name_zh_full TEXT NOT NULL,           
  name_en_full TEXT NOT NULL,           
  hkid_prefix TEXT NOT NULL,            
  phone TEXT NOT NULL,                  
  status TEXT NOT NULL DEFAULT 'PENDING', 
  applied_at TEXT NOT NULL DEFAULT (datetime('now')),
  sent_at TEXT DEFAULT NULL,            
  notes TEXT DEFAULT '', card_no TEXT,                
  FOREIGN KEY (member_no) REFERENCES members(member_no)
);
CREATE TABLE member_groups (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE NOT NULL, description TEXT DEFAULT '', color TEXT DEFAULT '#4caf50', created_at TEXT NOT NULL DEFAULT (DATETIME('now')));
CREATE TABLE member_kyc (id INTEGER PRIMARY KEY AUTOINCREMENT, member_no TEXT NOT NULL UNIQUE REFERENCES members (member_no) ON DELETE CASCADE, id_prefix TEXT NOT NULL DEFAULT '', id_doc_r2_key TEXT NOT NULL DEFAULT '', bank_name TEXT NOT NULL DEFAULT '', bank_acc_no TEXT NOT NULL DEFAULT '', submitted_at TEXT NOT NULL DEFAULT (DATETIME('now')), verified_at TEXT DEFAULT NULL, verified_by TEXT DEFAULT NULL, status TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'VERIFIED', 'REJECTED')), notes TEXT DEFAULT '', email TEXT NOT NULL DEFAULT '', referral_phone TEXT NOT NULL DEFAULT '', referral_name TEXT NOT NULL DEFAULT '', swift_code TEXT NOT NULL DEFAULT '');
CREATE TABLE members (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  member_no TEXT UNIQUE NOT NULL,         
  tier TEXT NOT NULL DEFAULT 'PRIMARY',   
  name_zh TEXT NOT NULL,                  
  phone TEXT NOT NULL,                    
  name_en TEXT DEFAULT '',                
  gender TEXT DEFAULT '',                 
  birth_year INTEGER DEFAULT NULL,        
  district TEXT DEFAULT '',               
  id_prefix TEXT DEFAULT '',              
  parent_no TEXT DEFAULT '',              
  parent_name TEXT DEFAULT '',            
  relation TEXT DEFAULT '',              
  roadshow TEXT DEFAULT 'walk-in',        
  kyc_status TEXT DEFAULT 'PENDING',      
  role TEXT DEFAULT 'CoExplorery',        
  notes TEXT DEFAULT '',                  
  expires_at TEXT NOT NULL,              
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, status TEXT NOT NULL DEFAULT 'ACTIVE', source TEXT NOT NULL DEFAULT 'walk-in', referrer_no TEXT DEFAULT '', roadshow_location TEXT DEFAULT '', admin_notes TEXT DEFAULT '', verified_at TEXT, group_id INTEGER DEFAULT NULL, wa_clicked_at TEXT DEFAULT NULL, wa_channel TEXT DEFAULT NULL, re_verify INTEGER DEFAULT 0);
CREATE TABLE payroll_records (id INTEGER PRIMARY KEY AUTOINCREMENT, roadshow_code TEXT NOT NULL, cw_no TEXT NOT NULL, total_minutes INTEGER NOT NULL DEFAULT 0, hourly_rate INTEGER NOT NULL DEFAULT 0, wage_amount INTEGER NOT NULL DEFAULT 0, transport_total INTEGER NOT NULL DEFAULT 0, meal_total INTEGER NOT NULL DEFAULT 0, total_payable INTEGER NOT NULL DEFAULT 0, brand_ref TEXT, status TEXT NOT NULL DEFAULT 'PENDING', pay_due_date TEXT, paid_at TEXT, paid_by TEXT, created_at TEXT NOT NULL DEFAULT (DATETIME('now')), updated_at TEXT NOT NULL DEFAULT (DATETIME('now')), UNIQUE (roadshow_code, cw_no));
CREATE TABLE products (id INTEGER PRIMARY KEY AUTOINCREMENT, name_zh TEXT NOT NULL /* 產品中文名 */, name_en TEXT NOT NULL /* 產品英文名 */, brand TEXT /* 品牌／供應商 */, sku TEXT /* 貨號 SKU（選填） */, category TEXT /* 分類（醬料／飲品／紙品…） */, unit TEXT /* 單位（支／包／盒） */, cost REAL DEFAULT 0 /* 成本價 */, price REAL DEFAULT 0 /* 建議零售價 */, description TEXT /* 產品描述 */, photo_url TEXT /* 產品相片連結（URL） */, active INTEGER DEFAULT 1 /* 1=使用中 0=停用 */, created_at TEXT NOT NULL DEFAULT (DATETIME('now')));
CREATE TABLE project_counter (id INTEGER PRIMARY KEY DEFAULT 1, next_val INTEGER NOT NULL DEFAULT 0);
CREATE TABLE project_ledger (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects (id) ON DELETE CASCADE, entry_type TEXT NOT NULL CHECK (entry_type IN ('INCOME' /* 直接收入 */, 'DIRECT_COST' /* 直接支出 */, 'PARTNER_SETTLEMENT' /* 供應商結算（分帳前，CoPartnery） */, 'FIXED_DEDUCTION' /* 分帳前固定支出（如運費） */)), co_partner_id INTEGER DEFAULT NULL REFERENCES co_partners (id) ON DELETE SET NULL, description TEXT NOT NULL DEFAULT '', amount_cents INTEGER NOT NULL DEFAULT 0 /* 正數；INCOME 為收，其餘為支 */, recorded_by TEXT NOT NULL DEFAULT 'admin', created_at TEXT NOT NULL DEFAULT (DATETIME('now')));
CREATE TABLE project_participants (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects (id) ON DELETE CASCADE, holder_no TEXT NOT NULL REFERENCES role_holders (holder_no) ON DELETE CASCADE, role TEXT NOT NULL CHECK (role IN ('COLEADERY', 'COLINKERY')), team_share_bps INTEGER NOT NULL DEFAULT 10000 /* 團隊內分帳 bps；單人項目=10000 */, confirm_status /* 同一 project_id + role 的所有 participant team_share_bps 加總必須 = 10000 */ /* 由應用層驗證 */ TEXT NOT NULL DEFAULT 'CONFIRMED' CHECK (confirm_status IN ('PENDING', 'CONFIRMED')), created_at TEXT NOT NULL DEFAULT (DATETIME('now')), UNIQUE (project_id, holder_no, role));
CREATE TABLE project_shares (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL UNIQUE REFERENCES projects (id) ON DELETE CASCADE, pct_coleadery INTEGER NOT NULL DEFAULT 0 /* CoLeadery 份額 bps */, pct_colinkery INTEGER NOT NULL DEFAULT 0 /* CoLinkery 份額 bps */, pct_coownery INTEGER NOT NULL DEFAULT 0 /* CoOwnery 池 bps */, pct_cosupportery INTEGER NOT NULL DEFAULT 0 /* CoSupportery 池 bps */, pct_mutual_fund INTEGER NOT NULL DEFAULT 0 /* 互助基金 bps */, pct_platform_fee INTEGER NOT NULL DEFAULT 0 /* 平台費 bps */, pct_special_account INTEGER NOT NULL DEFAULT 0 /* 特別資金帳戶 bps */, special_flag /* 七項加總 = 10000 由應用層強制驗證（SQLite CHECK 不支援欄位間加法） */ INTEGER NOT NULL DEFAULT 0 /* 1 = 特殊結構需審批 */, created_at TEXT NOT NULL DEFAULT (DATETIME('now')), updated_at TEXT NOT NULL DEFAULT (DATETIME('now')));
CREATE TABLE projects (id INTEGER PRIMARY KEY AUTOINCREMENT, project_code TEXT NOT NULL UNIQUE /* PRJ0001 */, name TEXT NOT NULL, scenario TEXT NOT NULL CHECK (scenario IN ('PURE_B2C', 'B2C_TO_B2B', 'PURE_B2B')), stage TEXT NOT NULL DEFAULT 'STARTUP' CHECK (stage IN ('STARTUP', 'GROWTH', 'SPECIAL')), business_type TEXT DEFAULT '' /* 業態：日用品/餐飲/服務等 */, status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT', 'ACTIVE', 'SETTLING', 'SETTLED', 'CLOSED')), notes TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT (DATETIME('now')));
CREATE TABLE roadshow_geo (id INTEGER PRIMARY KEY AUTOINCREMENT, roadshow_code TEXT NOT NULL UNIQUE, latitude REAL, longitude REAL, geofence_radius INTEGER NOT NULL DEFAULT 250, headcount_needed INTEGER NOT NULL DEFAULT 0, session_hourly_rate INTEGER NOT NULL DEFAULT 0, transport_allowance INTEGER NOT NULL DEFAULT 0, meal_allowance INTEGER NOT NULL DEFAULT 0, brand_ref TEXT, created_at TEXT NOT NULL DEFAULT (DATETIME('now')), updated_at TEXT NOT NULL DEFAULT (DATETIME('now')));
CREATE TABLE roadshow_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  roadshow_code TEXT NOT NULL,
  member_no TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE roadshows (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT UNIQUE NOT NULL /* Short unique code e.g. "RS2024-001" */, store_id INTEGER /* FK -> jhc_stores.id */, store_code TEXT /* Denormalised for convenience */, name TEXT NOT NULL /* Display name of this roadshow */, start_date TEXT /* ISO date "YYYY-MM-DD" */, end_date TEXT /* ISO date "YYYY-MM-DD" */, status TEXT NOT NULL DEFAULT 'active' /* active | inactive | ended */, notes TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT (DATETIME('now')), FOREIGN KEY (store_id) REFERENCES jhc_stores (id));
CREATE TABLE role_applications (id INTEGER PRIMARY KEY AUTOINCREMENT, member_no TEXT NOT NULL REFERENCES members (member_no) ON DELETE CASCADE, role TEXT NOT NULL CHECK (role IN ('COLEADERY', 'COLINKERY')), applicant_type TEXT NOT NULL CHECK (applicant_type IN ('INDIVIDUAL', 'GROUP', 'COMPANY')), name_zh TEXT NOT NULL, name_en TEXT NOT NULL, id_prefix TEXT DEFAULT '' /* 身份證前綴（個人） */, id_doc_r2_key TEXT DEFAULT '' /* 身份證 R2 key（個人/公司BR） */, address TEXT DEFAULT '', phone TEXT DEFAULT '', bank_name TEXT DEFAULT '', bank_acc_no TEXT DEFAULT '', company_name TEXT DEFAULT '' /* 公司名（公司身份） */, company_br TEXT DEFAULT '' /* BR號 */, industry_background TEXT DEFAULT '', team_size INTEGER DEFAULT NULL /* 團隊人數（GROUP身份） */, team_notes TEXT DEFAULT '' /* 團隊意向（前端填寫） */, status TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED')), review_notes TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT (DATETIME('now')), reviewed_at TEXT DEFAULT NULL);
CREATE TABLE role_holder_counters (role TEXT PRIMARY KEY /* 'COLEADERY' / 'COLINKERY' */, next_val INTEGER NOT NULL DEFAULT 0);
CREATE TABLE role_holders (id INTEGER PRIMARY KEY AUTOINCREMENT, holder_no TEXT NOT NULL UNIQUE /* CL000001 / CK000001 */, member_no TEXT NOT NULL REFERENCES members (member_no) ON DELETE CASCADE, role TEXT NOT NULL CHECK (role IN ('COLEADERY', 'COLINKERY')), applicant_type TEXT NOT NULL CHECK (applicant_type IN ('INDIVIDUAL', 'GROUP', 'COMPANY')), name_zh TEXT NOT NULL, name_en TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'SUSPENDED')), created_at TEXT NOT NULL DEFAULT (DATETIME('now')));
CREATE TABLE session_applications (id INTEGER PRIMARY KEY AUTOINCREMENT, roadshow_code TEXT NOT NULL, cw_no TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', note TEXT, created_at TEXT NOT NULL DEFAULT (DATETIME('now')), updated_at TEXT NOT NULL DEFAULT (DATETIME('now')), UNIQUE (roadshow_code, cw_no));
CREATE TABLE session_assignments (id INTEGER PRIMARY KEY AUTOINCREMENT, roadshow_code TEXT NOT NULL, cw_no TEXT NOT NULL, assigned_hourly_rate INTEGER NOT NULL DEFAULT 0, assigned_by TEXT, created_at TEXT NOT NULL DEFAULT (DATETIME('now')), UNIQUE (roadshow_code, cw_no));
CREATE TABLE settings (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE survey_questions (id INTEGER PRIMARY KEY AUTOINCREMENT, survey_id INTEGER NOT NULL, seq INTEGER NOT NULL, qtype TEXT NOT NULL, text_zh TEXT NOT NULL, options_json TEXT, required INTEGER NOT NULL DEFAULT 1);
CREATE TABLE survey_responses (id INTEGER PRIMARY KEY AUTOINCREMENT, survey_id INTEGER NOT NULL, member_no TEXT, roadshow_code TEXT, answers_json TEXT NOT NULL, submitted_at TEXT NOT NULL DEFAULT (DATETIME('now', '+8 hours')));
CREATE TABLE surveys (id INTEGER PRIMARY KEY AUTOINCREMENT, title_zh TEXT NOT NULL, product_id INTEGER, vendor TEXT, status TEXT NOT NULL DEFAULT 'OPEN', created_at TEXT NOT NULL DEFAULT (DATETIME('now', '+8 hours')));
CREATE TABLE team_invites (id INTEGER PRIMARY KEY AUTOINCREMENT, token TEXT NOT NULL UNIQUE, app_id INTEGER NOT NULL REFERENCES role_applications (id) ON DELETE CASCADE, member_no TEXT NOT NULL, name_zh TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', share_pct REAL NOT NULL DEFAULT 0, confirmed INTEGER NOT NULL DEFAULT 0, confirmed_at TEXT DEFAULT NULL, created_at TEXT NOT NULL DEFAULT (DATETIME('now')), expires_at TEXT NOT NULL);
CREATE TABLE useful_links (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, link_type TEXT NOT NULL CHECK (link_type IN ('phone', 'whatsapp', 'url', 'text')), content TEXT NOT NULL, sort_order INTEGER DEFAULT 0, is_active INTEGER DEFAULT 1, created_at TEXT DEFAULT (DATETIME('now')));
CREATE TABLE wallet_entries (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects (id) ON DELETE CASCADE, holder_no TEXT DEFAULT NULL /* 實際角色持有人；池類為 NULL */, role_or_pool TEXT NOT NULL CHECK (role_or_pool IN ('COLEADERY', 'COLINKERY', 'COOWNERY_POOL', 'COSUPPORTERY_POOL', 'MUTUAL_FUND', 'PLATFORM_FEE', 'SPECIAL_ACCOUNT')), amount_cents INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'PENDING_CONFIRM' CHECK (status IN ('PENDING_CONFIRM' /* 待確認 */, 'POSTED' /* 已入帳 */, 'PENDING_PAYOUT' /* 待出款 */, 'PAID' /* 已出款 */, 'RESERVED' /* 池類：已預留未分配 */)), paid_at TEXT DEFAULT NULL, hash TEXT DEFAULT NULL /* SHA-256 存證 */, created_at TEXT NOT NULL DEFAULT (DATETIME('now')));
CREATE INDEX idx_admin_sessions_expires ON admin_sessions(expires_at);
CREATE INDEX idx_admin_sessions_token ON admin_sessions(token);
CREATE INDEX idx_app_contents_section_status_sort ON app_contents(section, status, sort_order);
CREATE INDEX idx_apply_cw ON session_applications(cw_no);
CREATE INDEX idx_apply_rs ON session_applications(roadshow_code);
CREATE INDEX idx_apply_stat ON session_applications(status);
CREATE INDEX idx_assign_cw ON session_assignments(cw_no);
CREATE INDEX idx_assign_rs ON session_assignments(roadshow_code);
CREATE INDEX idx_att_cw ON attendance_records(cw_no);
CREATE INDEX idx_att_rs ON attendance_records(roadshow_code);
CREATE INDEX idx_auth_cards_holder ON authorization_cards(holder_no);
CREATE INDEX idx_auth_cards_token ON authorization_cards(token);
CREATE INDEX idx_bundle_addons_bundle ON bundle_addons(bundle_id);
CREATE INDEX idx_bundle_gifts_bundle ON bundle_gifts(bundle_id);
CREATE INDEX idx_bundle_items_bundle ON bundle_items(bundle_id);
CREATE INDEX idx_bundles_status ON bundles(status);
CREATE INDEX idx_cw_member ON co_workery(member_no);
CREATE INDEX idx_cw_phone ON co_workery(phone);
CREATE INDEX idx_cw_status ON co_workery(status);
CREATE INDEX idx_feedback_messages_thread_id ON feedback_messages(thread_id);
CREATE INDEX idx_feedback_threads_member_no ON feedback_threads(member_no);
CREATE INDEX idx_jhc_stores_code ON jhc_stores(store_code);
CREATE INDEX idx_jhc_stores_district ON jhc_stores(district);
CREATE INDEX idx_job_apps_job_id ON job_applications(job_id);
CREATE INDEX idx_job_apps_member_no ON job_applications(member_no);
CREATE INDEX idx_ledger_project ON project_ledger(project_id);
CREATE INDEX idx_medical_member ON medical_card_applications(member_no);
CREATE INDEX idx_medical_status ON medical_card_applications(status);
CREATE INDEX idx_members_kyc ON members(kyc_status);
CREATE INDEX idx_members_parent ON members(parent_no);
CREATE INDEX idx_members_phone ON members(phone);
CREATE INDEX idx_members_re_verify ON members(re_verify);
CREATE INDEX idx_members_referrer ON members(referrer_no);
CREATE INDEX idx_members_roadshow ON members(roadshow);
CREATE INDEX idx_members_source ON members(source);
CREATE INDEX idx_members_status ON members(status);
CREATE INDEX idx_members_tier ON members(tier);
CREATE INDEX idx_members_wa_channel ON members(wa_channel);
CREATE INDEX idx_members_wa_clicked ON members(wa_clicked_at);
CREATE INDEX idx_pay_cw ON payroll_records(cw_no);
CREATE INDEX idx_pay_rs ON payroll_records(roadshow_code);
CREATE INDEX idx_pay_status ON payroll_records(status);
CREATE INDEX idx_products_active ON products(active);
CREATE INDEX idx_products_category ON products(category);
CREATE INDEX idx_proj_participants_holder ON project_participants(holder_no);
CREATE INDEX idx_proj_participants_project ON project_participants(project_id);
CREATE INDEX idx_roadshow_log_code ON roadshow_log(roadshow_code);
CREATE INDEX idx_roadshows_code ON roadshows(code);
CREATE INDEX idx_roadshows_status ON roadshows(status);
CREATE INDEX idx_roadshows_store ON roadshows(store_id);
CREATE INDEX idx_role_applications_member ON role_applications(member_no);
CREATE INDEX idx_role_applications_status ON role_applications(status);
CREATE INDEX idx_role_holders_member ON role_holders(member_no);
CREATE INDEX idx_role_holders_role ON role_holders(role);
CREATE INDEX idx_rsgeo_code ON roadshow_geo(roadshow_code);
CREATE INDEX idx_sq_survey ON survey_questions(survey_id);
CREATE INDEX idx_sr_member ON survey_responses(member_no);
CREATE INDEX idx_sr_survey ON survey_responses(survey_id);
CREATE INDEX idx_surveys_product ON surveys(product_id);
CREATE INDEX idx_surveys_status ON surveys(status);
CREATE INDEX idx_team_invites_app_id ON team_invites(app_id);
CREATE INDEX idx_team_invites_token ON team_invites(token);
CREATE INDEX idx_useful_links_sort ON useful_links(sort_order);
CREATE INDEX idx_wallet_holder ON wallet_entries(holder_no);
CREATE INDEX idx_wallet_project ON wallet_entries(project_id);
